local WrapperFactory = require(script.ExtensionsWrapperFactory)

local module = {} :: IExtensionsWrapper

-- todo, assert exist
local ExtensionsFolder = game.ReplicatedStorage._robloxManifest.Extensions

-- 包装一个对象，为其添加指定接口的扩展方法
-- @param interfaceName string 接口名称
-- @param object table 被包装的对象
module.Wrap = function(interfaceName: string, object: {})
	assert(type(interfaceName) == "string", "interfaceName must be a string")
	local wrapperModuleScript = ExtensionsFolder:FindFirstChild(interfaceName .. "_extensions")
	if wrapperModuleScript then
		local warpper = WrapperFactory(wrapperModuleScript)
		warpper(object)
	end
end

return module
